{
  "name": "@smthrs/repo-targets",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "smthrs": {
    "group": "tooling"
  },
  "description": "Build defaults and AI review rules for the Smithers repository.",
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "test": "vitest run",
    "check": "vibelang --noEmit"
  },
  "dependencies": {
    "@effect/sql-pg": "4.0.5",
    "@smthrs/targets": "workspace:*",
    "effect": "4.0.5"
  },
  "devDependencies": {
    "typescript": "5.9.3",
    "vibelang": "0.0.8",
    "vibelang-vite": "0.0.8",
    "vitest": "5.0.0",
    "@smthrs/plan": "workspace:*",
    "@vitest/coverage-v8": "5.0.0",
    "fast-check": "4.9.0",
    "vibelang-runtime": "0.0.8",
    "vibelang-unplugin": "0.0.8"
  }
}

import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import vibelang from "vibelang-vite"
import { defineConfig } from "vitest/config"

export default defineConfig({
  // Tests start Node on source that reaches VibeLang packages; register: true loads .vibe in those processes.
  plugins: [vibelang({ project: "tsconfig.json", register: true })],
  test: {
    globalSetup: [
      fileURLToPath(new URL("test-utils/test-schemas.ts", import.meta.url)),
      fileURLToPath(new URL("test-utils/coverage-teardown.mjs", import.meta.url)),
      fileURLToPath(new URL("test-utils/test-process-environment.mjs", import.meta.url))
    ],
    include: ["test/**/*.test.{ts,vibe}"],
    testTimeout: 30_000,
    hookTimeout: 30_000,
    coverage: {
      enabled: true,
      provider: "v8",
      reportsDirectory: join(tmpdir(), `flows-repo-targets-coverage-${process.pid}`),
      include: ["src/**", "ci/**/*.ts"],
      thresholds: {
        branches: 100,
        functions: 100,
        lines: 100,
        statements: 100
      }
    }
  }
})
